using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace MRS;
internal sealed record ReceiverProfile(string Id,string Name,string Role="Independent",string Group="",int Priority=0){public string Display=>$"{Name} [{Id}] - {Role}"+(Group.Length>0?" / "+Group:"");}
public partial class MainWindow
{
 private ReceiverProfile fleetProfile=null!;private string fleetFile="";private bool fleetVoiceBusy,fleetPaused;private long fleetLeaseEpoch,fleetScope;private MainWindow? fleetOwner;private string fleetLease="";private DateTimeOffset fleetAssigned;private readonly Dictionary<MainWindow,string> fleetLeases=[];
 private static string CallKey(TrunkCall c)=>$"{c.Protocol}:{c.Hz}:{c.Slot}:{c.Talkgroup}:{c.Nac}";
 private IEnumerable<MainWindow> FleetWindows()=>Application.Current.Windows.OfType<MainWindow>().Where(w=>!w.closing&&w.diagnosticWorkspace==diagnosticWorkspace);
 private Dictionary<string,ReceiverProfile> ReadFleet(){try{return File.Exists(fleetFile)?JsonSerializer.Deserialize<Dictionary<string,ReceiverProfile>>(File.ReadAllText(fleetFile))??[]:[];}catch(Exception ex){throw new IOException("Receiver definitions could not be read; left unchanged: "+ex.Message);}}
 private void SaveFleet(ReceiverProfile p){var all=ReadFleet();all[p.Id]=p;Directory.CreateDirectory(Path.GetDirectoryName(fleetFile)!);string temp=fleetFile+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(all,new JsonSerializerOptions{WriteIndented=true}));File.Move(temp,fleetFile,true);}
 private void InitializeFleet(){fleetFile=Path.Combine(diagnosticWorkspace?dataFolder:Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MRS"),"receiver-workspaces.json");try{fleetProfile=ReadFleet().GetValueOrDefault(workspaceSlot)??new(workspaceSlot,"Receiver "+workspaceSlot);}catch(Exception ex){fleetProfile=new(workspaceSlot,"Receiver "+workspaceSlot);Log(ex.Message);}ReflectFleet();}
 private void ReflectFleet(){WorkspaceLabel.Text=fleetProfile.Name;Title="M.R.S. - "+fleetProfile.Name;}
 private MainWindow OpenFleetReceiver(ReceiverProfile p){var old=FleetWindows().FirstOrDefault(w=>w.workspaceSlot==p.Id);if(old!=null){old.Activate();return old;}string? diagnosticRoot=diagnosticWorkspace?Path.Combine(dataFolder,"fleet",p.Id):null;var next=new MainWindow(diagnosticWorkspace,p.Id,diagnosticRoot);next.fleetProfile=p;next.fleetFile=fleetFile;next.ReflectFleet();next.Show();return next;}
 private void OpenFleetManager(){try{CreateFleetManager().ShowDialog();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Receiver definitions");}}
 private Window CreateFleetManager()
 {
  var win=new Window{Owner=this,Title="Receiver management",Width=800,Height=620};var root=new DockPanel{Margin=new(12)};win.Content=root;var list=new ListBox{MinHeight=90,MaxHeight=130,DisplayMemberPath="Display"};DockPanel.SetDock(list,Dock.Top);root.Children.Add(list);var controls=new WrapPanel();DockPanel.SetDock(controls,Dock.Bottom);root.Children.Add(controls);var form=new StackPanel();root.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var name=new TextBox();var role=new ComboBox{ItemsSource=new[]{"Independent","Trunk control","Trunk voice"},SelectedIndex=0};var group=new TextBox();var priority=new TextBox{Text="0"};foreach(var (title,c) in new (string,FrameworkElement)[]{("Receiver name",name),("Role",role),("Trunk group (same explicit group on control and voice receivers)",group),("Voice receiver priority (lower first)",priority)}){form.Children.Add(new TextBlock{Text=title,Foreground=Brushes.White});form.Children.Add(c);}var note=new TextBlock{Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Text="Open a workspace and select/start its SDR there. Role and group changes stop following. Removing a definition closes its workspace but keeps recordings, frequency lists and profile files. Distinct physical devices are required; ambiguous serials require manual selection."};form.Children.Add(note);var status=new TextBlock{Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,0)};form.Children.Add(status);var clock=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};clock.Tick+=(_,_)=>status.Text=string.Join("\n",FleetWindows().Select(w=>$"{w.fleetProfile.Name}: {w.receiver.ReceiverName} / {w.receiver.AppliedChannel?.Frequency/1e6:F6} MHz / {w.fleetProfile.Role} / {(w.fleetOwner!=null?"assigned by "+w.fleetOwner.fleetProfile.Name:w.fleetPaused?"pool paused":"ready/independent")}"));win.Loaded+=(_,_)=>clock.Start();win.Closed+=(_,_)=>clock.Stop();
  void Refresh(){string? selectedId=(list.SelectedItem as ReceiverProfile)?.Id;var data=ReadFleet();foreach(var w in FleetWindows())data[w.workspaceSlot]=w.fleetProfile;list.ItemsSource=data.Values.OrderBy(p=>p.Id).ToArray();list.SelectedItem=list.Items.OfType<ReceiverProfile>().FirstOrDefault(p=>p.Id==selectedId)??list.Items.OfType<ReceiverProfile>().FirstOrDefault();}
  list.SelectionChanged+=(_,_)=>{if(list.SelectedItem is ReceiverProfile p){name.Text=p.Name;role.SelectedItem=p.Role;group.Text=p.Group;priority.Text=p.Priority.ToString();}};
  void Button(string text,Action action){var b=new Button{Content=text,Padding=new(9,6,9,6)};controls.Children.Add(b);b.Click+=(_,_)=>{try{action();Refresh();}catch(Exception ex){note.Text=ex.Message;}};}
  Button("Add receiver",()=>{var used=ReadFleet().Keys.Concat(FleetWindows().Select(w=>w.workspaceSlot)).ToHashSet();string id=Enumerable.Range('A',26).Select(n=>((char)n).ToString()).FirstOrDefault(n=>!used.Contains(n))??throw new IOException("Maximum 26 receiver workspaces.");var p=new ReceiverProfile(id,"Receiver "+id);SaveFleet(p);OpenFleetReceiver(p);});
  Button("Open",()=>{if(list.SelectedItem is ReceiverProfile p)OpenFleetReceiver(p);});
  Button("Save assignment",()=>{if(list.SelectedItem is not ReceiverProfile p)return;if(name.Text.Trim().Length is <1 or >80||group.Text.Length>100||!int.TryParse(priority.Text,out int rank))throw new IOException("Enter a receiver name, group up to 100 characters and numeric priority.");var next=p with{Name=name.Text.Trim(),Role=role.SelectedItem?.ToString()??"Independent",Group=group.Text.Trim(),Priority=rank};if(next.Role!="Independent"&&next.Group.Length==0)throw new IOException("Trunk roles require an explicit group.");SaveFleet(next);if(FleetWindows().FirstOrDefault(w=>w.workspaceSlot==p.Id) is {} w){w.StopTrunk(false);w.ReleaseFleetAssignments();w.fleetProfile=next;w.fleetPaused=false;w.ReflectFleet();}});
  Button("Remove receiver",()=>{if(list.SelectedItem is not ReceiverProfile p)return;if(FleetWindows().FirstOrDefault(w=>w.workspaceSlot==p.Id) is {} w)w.Close();var data=ReadFleet();data.Remove(p.Id);string tmp=fleetFile+".tmp";File.WriteAllText(tmp,JsonSerializer.Serialize(data));File.Move(tmp,fleetFile,true);});Refresh();return win;
 }
 private void ReleaseFleetAssignments(){foreach(var w in FleetWindows().Where(w=>w.fleetOwner==this).ToArray())w.EndFleetVoice("Control receiver stopped");if(fleetOwner!=null){fleetPaused=true;fleetLeaseEpoch++;var owner=fleetOwner;fleetOwner=null;owner.fleetLeases.Remove(this);fleetVoiceBusy=false;fleetLease="";}fleetLeases.Clear();}
 private void EndFleetVoice(string reason){var owner=fleetOwner;fleetLeaseEpoch++;fleetOwner=null;fleetLease="";fleetVoiceBusy=false;if(owner!=null)owner.fleetLeases.Remove(this);StopTrunk(false);trunkStatus.Text=reason;}
 private async Task BeginFleetVoice(MainWindow owner,TrunkCall call)
 {
  long reservation=++fleetLeaseEpoch;fleetVoiceBusy=true;fleetOwner=owner;fleetLease=CallKey(call);fleetAssigned=DateTimeOffset.UtcNow;try{StopActivity("Trunk voice assignment");StopFolderScan("Trunk voice assignment");P25Packets.VoiceToggle.IsChecked=false;digitalMode.SelectedIndex=0;Aviation.Stop("Trunk voice assignment");HdRecordings.StopLive("Trunk voice assignment");Television.StopLive("Trunk voice assignment");var channel=new ChannelSettings(call.Hz,"NFM",call.Protocol=="P25"?16000:12500);if(!receiver.CanTune(call.Hz)||channel.Width>receiver.AppliedBandwidth)throw new IOException("Assigned voice channel exceeds this receiver's coverage.");if(channel.Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth))receiver.SetChannel(channel);else await receiver.Retune(call.Hz,channel);for(int n=0;n<250&&fleetLeaseEpoch==reservation&&fleetOwner==owner&&(receiver.AppliedChannel?.Frequency!=call.Hz||!channel.Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth));n++)await Task.Delay(20);if(fleetLeaseEpoch!=reservation||fleetOwner!=owner||closing||owner.closing)return;if(receiver.AppliedChannel?.Frequency!=call.Hz||!channel.Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth))throw new IOException("Receiver did not report the assigned capture within five seconds.");engine.RetuneBoundary();trunkAudioKey="";trunkRadio.StartExternal(call,owner.fleetProfile.Name);lock(trunkRadio.Sync){trunkRadio.Model.HangSeconds=owner.trunkRadio.Model.HangSeconds;trunkRadio.Model.MaximumSeconds=owner.trunkRadio.Model.MaximumSeconds;}trunkStatus.Text=$"Voice assigned by {owner.fleetProfile.Name}: TG {call.Talkgroup}";}catch(Exception ex){if(reservation==fleetLeaseEpoch){EndFleetVoice("Voice assignment failed: "+ex.Message);fleetPaused=true;owner.Log(fleetProfile.Name+": "+ex.Message);}}finally{if(reservation==fleetLeaseEpoch)fleetVoiceBusy=false;}
 }
 private bool FleetControlActive=>fleetProfile?.Role=="Trunk control"&&fleetProfile.Group.Length>0&&trunkRadio.Running&&fleetOwner==null;
 private void TickFleet()
 {
  if(fleetOwner!=null){if(fleetOwner.closing||!fleetOwner.FleetControlActive||fleetOwner.fleetProfile.Group!=fleetProfile.Group||!rfMode||receiver.IsReplay){EndFleetVoice("Assignment released");return;}if(!fleetVoiceBusy&&!trunkRadio.Running)EndFleetVoice("Voice lease ended");return;}
  if(!FleetControlActive){if(fleetLeases.Count>0)ReleaseFleetAssignments();return;}
  if(fleetScope!=trunkRadio.Model.ScopeVersion){ReleaseFleetAssignments();fleetScope=trunkRadio.Model.ScopeVersion;}TrunkCall[] calls;lock(trunkRadio.Sync)calls=trunkRadio.Model.AvailableCalls(DateTimeOffset.UtcNow);
  foreach(var pair in fleetLeases.ToArray()){var w=pair.Key;if(w.closing||w.fleetOwner!=this){fleetLeases.Remove(w);continue;}if((DateTimeOffset.UtcNow-w.fleetAssigned).TotalSeconds>=trunkRadio.Model.MaximumSeconds)w.EndFleetVoice("Maximum call timer");}
  var assigned=fleetLeases.Values.ToHashSet();foreach(var call in calls){string key=CallKey(call);if(assigned.Contains(key))continue;var target=FleetWindows().Where(w=>w!=this&&w.fleetProfile.Role=="Trunk voice"&&w.fleetProfile.Group==fleetProfile.Group&&w.fleetOwner==null&&!w.fleetVoiceBusy&&!w.fleetPaused&&w.rfMode&&!w.receiver.IsReplay&&!w.trunkRadio.Running&&w.receiver.SamplingMode==0&&w.receiver.CanTune(call.Hz)&&w.receiver.AppliedBandwidth>=(call.Protocol=="P25"?16000:12500)).OrderBy(w=>w.fleetProfile.Priority).ThenBy(w=>w.workspaceSlot).FirstOrDefault();if(target==null)break;fleetLeases[target]=key;assigned.Add(key);_=target.BeginFleetVoice(this,call);}
 }
}
